int loadR08(std::string filepath, ushort* &inputs, bool* &resets)
{
    std::ifstream file(filepath, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        std::cerr << "Error opening file!" << std::endl;
    }
    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);

    char* TAS = new char[size];

    if (size > 8 && file.read(TAS, size)) {
        std::cout << "Loaded TAS: " << filepath << std::endl;
    }
    else {
        std::cerr << "Error reading file!" << std::endl;
        return 0;
    }

    file.close();

    inputs = (ushort*)TAS;
    resets = new bool[size / 2];

	return size / 2;
}

int loadBK2(std::string filepath, ushort*& inputs, bool*& resets)
{
    ZipArchive::Ptr archive = ZipFile::Open(filepath);
    ZipArchiveEntry::Ptr entry = archive->GetEntry("Input Log.txt");
    if (entry->IsPasswordProtected()) return 0;

    std::istream* decompressStream = entry->GetDecompressionStream();

    std::string line;

    std::vector<ushort> vInputs;
    std::vector<bool> vResets;

    int len;

    while (std::getline(*decompressStream, line))
    {
        if (line.at(0) != '|') continue;

        std::stringstream ss(line);
        std::string token;
        int i = 0;

        ushort input = 0;
        bool reset = false;

        while (std::getline(ss, token, '|'))
        {
            if (i > 1)
            {
                ushort b = 0;

                for (int c = 0; c < token.size(); c++)
                {
                    switch (token.at(c))
                    {
                    case 'A': b |= 0x80; break;
                    case 'B': b |= 0x40; break;
                    case 's': b |= 0x20; break;
                    case 'S': b |= 0x10; break;
                    case 'U': b |= 0x08; break;
                    case 'D': b |= 0x04; break;
                    case 'L': b |= 0x02; break;
                    case 'R': b |= 0x01; break;
                    default:  b |= 0x00; break;
                    }
                }

                if (i == 3) b <<= 8;
                input |= b;
            }
            else if (i == 1)
            {
                for (int c = 0; c < token.size(); c++)
                {
                    switch (token.at(c))
                    {
                    case 'r': reset = true; break;
                    default: break;
                    }
                }
            }

            i++;
        }

        vInputs.push_back(input);
        vResets.push_back(reset);

        len++;
    }

    inputs = new ushort[len];
    resets = new bool[len];

    for (int i = 0; i < len; i++)
    {
        inputs[i] = vInputs[i];
        resets[i] = vResets[i];
    }
    
    return len;
}